def drive(me, enemy, arena):
    if me.memory.get("p") is None:
        me.memory["p"] = 1
        print("prog loaded")
    if not me.can_drive:
        return (0.0, 0.0)
    tx = enemy.x
    ty = enemy.y
    if me.x * me.x + me.y * me.y > 27.8:
        tx = 0.0
        ty = 0.0
    b = bearing_to(tx, ty)
    d = distance_to(tx, ty)
    if abs(b) > 115.0:
        s = 1.0
        if b < 0.0:
            s = -1.0
        return (-0.85 * s, 0.85 * s)
    steer = b / 60.0
    if steer > 1.0:
        steer = 1.0
    elif steer < -1.0:
        steer = -1.0
    base = 1.0
    if d < 1.5:
        base = 0.85
    l = base - steer
    r = base + steer
    if l > 1.0:
        l = 1.0
    elif l < -1.0:
        l = -1.0
    if r > 1.0:
        r = 1.0
    elif r < -1.0:
        r = -1.0
    return (l, r)


def weapons(me, enemy, arena):
    w = me.weapons.get("front")
    if w is None or w.get("type") != "spinner":
        return None
    if w.get("health", 1.0) <= 0.0:
        return None
    return spin("front", 3000)

